// In-process tools the coordinator model may call (DESIGN.md §"Coordinator tools").
// Each tool validates its arguments, runs inside a TOOL span, and answers with JSON. Bad calls get an error
// message back, never a crash. The gate decides what ships: `promote` refuses any candidate the gate did not approve.
import { existsSync, readFileSync } from "node:fs";
import { join, resolve } from "node:path";
import { fetchCheckpoints } from "../ingest/fetch.ts";
import { parseCheckpoints } from "../ingest/parse.ts";
import { identify } from "../identity/index.ts";
import { ATTR } from "../obs/attributes.ts";
import { type SpanAttrs, withSpan } from "../obs/index.ts";
import { reviewSlug, summarizeSetups } from "../review/export.ts";
import { FailureCode, type GateDecision, type Outcome, type Replay, type Review, type Session } from "../types.ts";
import type { ToolCall, ToolSpec } from "../llm/types.ts";
import { checkPlan, type PlanRevision } from "./plan.ts";
import { replayRunner, type ReplayRunnerDeps } from "../replay/run.ts";

/** A gate decision as the coordinator records it: every rejection names its failed tasks. */
export interface Decision extends GateDecision {
  failed_tasks: string[];
}

export type FinishOutcome = "promoted" | "no_better_setup";

/** Everything a run has decided so far. JSON-serialisable: it is snapshotted into the events log for resume. */
export interface RunState {
  plans: PlanRevision[];
  decisions: Decision[];
  promoted: string | null;
  reverted: string[];
  /** Tasks that hit F6; excluded from later plans. */
  excludedTasks: string[];
  replayUsd: number;
  finished: { outcome: FinishOutcome; summary: string } | null;
  /** Messages for the coordinator to pass to the model before its next turn (replan requests). */
  notes: string[];
}

export function initialState(): RunState {
  return { plans: [], decisions: [], promoted: null, reverted: [], excludedTasks: [], replayUsd: 0, finished: null, notes: [] };
}

export interface ReplayBatch {
  replays: Replay[];
  cost_usd: number;
}

/** What the tools wrap. Methods that throw NotAvailableError report "not available yet" to the model. */
export interface ToolBackend {
  ingestRepo(a: { repo: string }): Promise<unknown>;
  getScorecard(a: { repo: string }): Promise<unknown>;
  /** A stratified task sample (≤ max), used when the model plans without naming tasks. */
  sampleTasks(a: { repo: string; max: number; exclude: string[] }): Promise<string[]>;
  runReplays(a: { plan_id: string; tasks: string[]; setups: string[]; max_cost_usd: number }): Promise<ReplayBatch>;
  getReplayResults(a: { plan_id: string; setup?: string }): Promise<Replay[]>;
  rerun(a: { plan_id: string; task: string; setup: string; max_cost_usd: number }): Promise<ReplayBatch>;
  classifyFailures(a: { plan_id: string; setup: string }): Promise<unknown>;
  /** Deterministic gate (DESIGN.md §"Gate"). The coordinator records it and cannot override it. */
  gate(a: { plan_id: string; candidate: string }): Promise<Omit<Decision, "failed_tasks"> & { failed_tasks?: string[] }>;
  promote(a: { candidate: string; decision: Decision }): Promise<unknown>;
  revert(a: { setup: string; reason: string }): Promise<unknown>;
}

export class NotAvailableError extends Error {
  constructor(what: string) {
    super(`not available yet: ${what}`);
  }
}

export interface ToolContext {
  runId: string;
  repo: string;
  budgetUsd: number;
  /** LLM plus replay spend so far. */
  spentUsd: () => number;
}

interface ToolDef {
  spec: ToolSpec;
  run(args: Record<string, unknown>, state: RunState, ctx: ToolContext, backend: ToolBackend, span: SpanSink): Promise<unknown>;
}

interface SpanSink {
  attrs: SpanAttrs;
}

/** An error the model caused (bad arguments, wrong order). Reported back to it as `{ok:false,error}`. */
export class ToolError extends Error {}

const str = (description: string) => ({ type: "string", description });
const strs = (description: string) => ({ type: "array", items: { type: "string" }, description });
const obj = (properties: Record<string, unknown>, required: string[] = []) => ({
  type: "object",
  properties,
  required,
  additionalProperties: false,
});

export function currentPlan(state: RunState): PlanRevision | null {
  return state.plans.at(-1) ?? null;
}

export function planId(runId: string, plan: PlanRevision): string {
  return `${runId}-p${plan.revision}`;
}

function requirePlan(state: RunState): PlanRevision {
  const plan = currentPlan(state);
  if (!plan) throw new ToolError("no plan yet: call plan_replays first");
  return plan;
}

function remaining(ctx: ToolContext): number {
  const left = ctx.budgetUsd - ctx.spentUsd();
  if (left <= 0) throw new ToolError(`budget exhausted: spent $${ctx.spentUsd().toFixed(4)} of $${ctx.budgetUsd}`);
  return left;
}

/** Records replay spend and F6 exclusions from a batch of replays. */
function absorb(state: RunState, replays: Replay[], cost: number): void {
  state.replayUsd += Number.isFinite(cost) && cost > 0 ? cost : 0;
  const f6 = [...new Set(replays.filter((r) => r.failure_codes.includes(FailureCode.F6)).map((r) => r.task_session_id))].filter(
    (t) => !state.excludedTasks.includes(t),
  );
  if (f6.length) {
    state.excludedTasks.push(...f6);
    state.notes.push(
      `F6 (environment or setup error) on task(s) ${f6.join(", ")}. They are excluded. Replan: call plan_replays with a resampled task set.`,
    );
  }
}

const TOOLS: ToolDef[] = [
  {
    spec: {
      name: "ingest_repo",
      description: "Fetch the repo's Entire checkpoints and list its sessions and setups.",
      parameters: obj({}),
    },
    run: (_a, _s, ctx, b) => b.ingestRepo({ repo: ctx.repo }),
  },
  {
    spec: {
      name: "get_scorecard",
      description: "The observational (level A) scorecard per setup, and the review's suspect label.",
      parameters: obj({}),
    },
    run: (_a, _s, ctx, b) => b.getScorecard({ repo: ctx.repo }),
  },
  {
    spec: {
      name: "plan_replays",
      description:
        "Write or revise plan.json. Give a one-paragraph rationale, the suspect setup, ≤ 3 candidate setup ids and ≤ 12 task session ids (omit tasks for a stratified sample). Call again to replan after a gate rejection or F6.",
      parameters: obj(
        {
          rationale: str("One paragraph: why these tasks and candidates."),
          suspect: { type: ["string", "null"], description: "The suspect (incumbent) setup id, or null." },
          candidates: strs("Candidate setup ids, at most 3."),
          tasks: strs("Task session ids, at most 12, stratified by difficulty tercile."),
          stop_rules: strs("Stop rules. Defaults apply when omitted."),
          budget_usd: { type: "number", description: "May lower, never raise, the run budget." },
          reason: str("Why you are (re)planning."),
        },
        ["rationale", "candidates"],
      ),
    },
    async run(a, state, ctx, b) {
      const input = { ...a };
      if (input.tasks === undefined) {
        input.tasks = await b.sampleTasks({ repo: ctx.repo, max: 12, exclude: state.excludedTasks });
      }
      const rejected = new Set(state.decisions.filter((d) => d.verdict === "reject").map((d) => d.candidate));
      const check = checkPlan(input, {
        budgetUsd: ctx.budgetUsd,
        previous: state.plans,
        excludedTasks: new Set(state.excludedTasks),
        rejected,
        reason: typeof a.reason === "string" && a.reason ? a.reason : state.plans.length ? "replan" : "initial",
      });
      if (!check.ok) throw new ToolError(`plan rejected: ${check.errors.join("; ")}`);
      state.plans.push(check.revision);
      return { plan_id: planId(ctx.runId, check.revision), ...check.revision };
    },
  },
  {
    spec: {
      name: "run_replays",
      description: "Replay the plan's tasks at their parent commits under the given setups (include the incumbent as control).",
      parameters: obj({ setups: strs("Setup ids to replay."), tasks: strs("Subset of the plan's tasks; default all.") }, ["setups"]),
    },
    async run(a, state, ctx, b, span) {
      const plan = requirePlan(state);
      const setups = a.setups as string[];
      if (setups.length === 0) throw new ToolError("setups: at least one setup id is required");
      const tasks = (a.tasks as string[] | undefined) ?? plan.body.tasks;
      const off = tasks.filter((t) => !plan.body.tasks.includes(t));
      if (off.length) throw new ToolError(`tasks not in the current plan: ${off.join(", ")}`);
      const batch = await b.runReplays({ plan_id: planId(ctx.runId, plan), tasks, setups, max_cost_usd: remaining(ctx) });
      absorb(state, batch.replays, batch.cost_usd);
      span.attrs.costUsd = batch.cost_usd;
      return batch;
    },
  },
  {
    spec: {
      name: "get_replay_results",
      description: "Replay rows for the current plan, optionally for one setup.",
      parameters: obj({ setup: str("Setup id.") }),
    },
    async run(a, state, ctx, b) {
      const plan = requirePlan(state);
      const replays = await b.getReplayResults({ plan_id: planId(ctx.runId, plan), setup: a.setup as string | undefined });
      absorb(state, replays, 0);
      return replays;
    },
  },
  {
    spec: {
      name: "rerun",
      description: "Rerun one task under one setup (for grader/judge disagreement or a split, up to k = 3).",
      parameters: obj({ task: str("Task session id."), setup: str("Setup id.") }, ["task", "setup"]),
    },
    async run(a, state, ctx, b, span) {
      const plan = requirePlan(state);
      span.attrs.task = a.task as string;
      span.attrs.setup = a.setup as string;
      const batch = await b.rerun({
        plan_id: planId(ctx.runId, plan),
        task: a.task as string,
        setup: a.setup as string,
        max_cost_usd: remaining(ctx),
      });
      absorb(state, batch.replays, batch.cost_usd);
      span.attrs.costUsd = batch.cost_usd;
      return batch;
    },
  },
  {
    spec: {
      name: "classify_failures",
      description: "Failure taxonomy (F1–F7) for one setup's replays in the current plan.",
      parameters: obj({ setup: str("Setup id.") }, ["setup"]),
    },
    async run(a, state, ctx, b) {
      const plan = requirePlan(state);
      return b.classifyFailures({ plan_id: planId(ctx.runId, plan), setup: a.setup as string });
    },
  },
  {
    spec: {
      name: "propose_rules_candidate",
      description: "Patch the suspect's rules file from its top failure codes into a new candidate.",
      parameters: obj({ setup: str("Setup id to mutate."), failure_codes: strs("Failure codes to answer.") }),
    },
    async run() {
      throw new NotAvailableError("propose_rules_candidate (src/candidates is not built)");
    },
  },
  {
    spec: {
      name: "gate",
      description: "Run the deterministic gate for one candidate against the incumbent on the current plan. Its verdict is final.",
      parameters: obj({ candidate: str("Candidate setup id.") }, ["candidate"]),
    },
    async run(a, state, ctx, b, span) {
      const plan = requirePlan(state);
      const candidate = a.candidate as string;
      if (!plan.body.candidates.includes(candidate)) throw new ToolError(`${candidate} is not a candidate in the current plan`);
      span.attrs.setup = candidate;
      const raw = await withSpan("GUARDRAIL", "gate", { setup: candidate, evidenceLevel: "B" }, () =>
        b.gate({ plan_id: planId(ctx.runId, plan), candidate }),
      );
      const decision: Decision = { ...raw, failed_tasks: raw.failed_tasks ?? [] };
      if (
        decision.candidate !== candidate ||
        decision.plan_id !== planId(ctx.runId, plan) ||
        (decision.verdict !== "promote" && decision.verdict !== "reject")
      ) {
        throw new Error(`gate returned a malformed decision for ${candidate}`);
      }
      state.decisions.push(decision);
      if (decision.verdict === "reject") {
        state.notes.push(
          `The gate rejected ${candidate}: ${decision.reasons.join("; ") || "no reasons given"}. Replan: call plan_replays with the next candidate, or finish with no_better_setup.`,
        );
      }
      return decision;
    },
  },
  {
    spec: {
      name: "promote",
      description: "Promote a candidate. Only works for a candidate the gate approved on the current plan.",
      parameters: obj({ candidate: str("Candidate setup id.") }, ["candidate"]),
    },
    async run(a, state, ctx, b, span) {
      const plan = requirePlan(state);
      const candidate = a.candidate as string;
      span.attrs.setup = candidate;
      if (state.promoted) throw new ToolError(`${state.promoted} is already promoted`);
      const decision = state.decisions.find(
        (d) => d.candidate === candidate && d.plan_id === planId(ctx.runId, plan) && d.verdict === "promote",
      );
      if (!decision) throw new ToolError(`the gate has not approved ${candidate} on the current plan; the gate decides what ships`);
      const res = await b.promote({ candidate, decision });
      state.promoted = candidate;
      return res;
    },
  },
  {
    spec: {
      name: "revert",
      description: "Revert a previously promoted setup.",
      parameters: obj({ setup: str("Setup id."), reason: str("Why.") }, ["setup", "reason"]),
    },
    async run(a, state, _ctx, b, span) {
      span.attrs.setup = a.setup as string;
      const res = await b.revert({ setup: a.setup as string, reason: a.reason as string });
      state.reverted.push(a.setup as string);
      if (state.promoted === a.setup) state.promoted = null;
      return res;
    },
  },
  {
    spec: {
      name: "finish",
      description:
        "End the run. outcome is \"promoted\" only after a successful promote; otherwise \"no_better_setup\" (a valid result). Summarise only what tools returned.",
      parameters: obj(
        { outcome: { type: "string", enum: ["promoted", "no_better_setup"] }, summary: str("What the tools showed.") },
        ["outcome", "summary"],
      ),
    },
    async run(a, state) {
      const outcome = a.outcome as FinishOutcome;
      if (outcome === "promoted" && !state.promoted) throw new ToolError("nothing was promoted; finish with no_better_setup");
      if (outcome === "no_better_setup" && state.promoted) throw new ToolError(`${state.promoted} was promoted; finish with promoted`);
      state.finished = { outcome, summary: a.summary as string };
      return state.finished;
    },
  },
];

export const TOOL_SPECS: ToolSpec[] = TOOLS.map((t) => t.spec);

type Prop = { type?: string | string[]; items?: { type: string }; enum?: string[] };

/** Checks parsed arguments against a tool's parameter schema. Returns the problems, empty when valid. */
export function validateArgs(spec: ToolSpec, args: unknown): string[] {
  if (typeof args !== "object" || args === null || Array.isArray(args)) return ["arguments must be a JSON object"];
  const rec = args as Record<string, unknown>;
  const props = (spec.parameters.properties ?? {}) as Record<string, Prop>;
  const required = (spec.parameters.required ?? []) as string[];
  const errors: string[] = [];
  for (const r of required) if (rec[r] === undefined) errors.push(`missing required argument "${r}"`);
  for (const [k, v] of Object.entries(rec)) {
    const p = props[k];
    if (!p) {
      errors.push(`unknown argument "${k}"`);
      continue;
    }
    if (v === undefined) continue;
    const types = Array.isArray(p.type) ? p.type : [p.type];
    const ok = types.some((t) =>
      t === "string"
        ? typeof v === "string"
        : t === "number"
          ? typeof v === "number" && Number.isFinite(v)
          : t === "null"
            ? v === null
            : t === "array"
              ? Array.isArray(v) && v.every((x) => typeof x === "string")
              : true,
    );
    if (!ok) errors.push(`argument "${k}" must be ${types.join(" or ")}${p.items ? ` of ${p.items.type}` : ""}`);
    else if (p.enum && !p.enum.includes(v as string)) errors.push(`argument "${k}" must be one of ${p.enum.join(", ")}`);
  }
  return errors;
}

const MAX_RESULT_CHARS = 20_000;

export interface ToolOutcome {
  /** The tool message content sent back to the model. */
  content: string;
  ok: boolean;
}

/**
 * Runs one tool call from the model. Unknown tools, malformed JSON, bad arguments, tool misuse and backend
 * failures all come back as `{"ok":false,"error":...}`; this function does not throw.
 */
export async function executeToolCall(
  call: ToolCall,
  state: RunState,
  ctx: ToolContext,
  backend: ToolBackend,
): Promise<ToolOutcome> {
  const reply = (ok: boolean, body: Record<string, unknown>): ToolOutcome => {
    let content = JSON.stringify({ ok, ...body });
    if (content.length > MAX_RESULT_CHARS) content = `${content.slice(0, MAX_RESULT_CHARS)}… [truncated]`;
    return { ok, content };
  };
  const def = TOOLS.find((t) => t.spec.name === call.name);
  if (!def) return reply(false, { error: `unknown tool "${call.name}". Available: ${TOOL_SPECS.map((t) => t.name).join(", ")}` });
  let args: unknown;
  try {
    args = call.arguments.trim() === "" ? {} : JSON.parse(call.arguments);
  } catch (err) {
    return reply(false, { error: `arguments are not valid JSON (${err instanceof Error ? err.message : String(err)})` });
  }
  const problems = validateArgs(def.spec, args);
  if (problems.length) return reply(false, { error: `invalid arguments for ${call.name}: ${problems.join("; ")}` });

  const sink: SpanSink = { attrs: { repo: ctx.repo } };
  return withSpan("TOOL", call.name, sink.attrs, async (span) => {
    try {
      const result = await def.run(args as Record<string, unknown>, state, ctx, backend, sink);
      if (sink.attrs.setup !== undefined) span.setAttribute(ATTR.setup, sink.attrs.setup);
      if (sink.attrs.task !== undefined) span.setAttribute(ATTR.task, sink.attrs.task);
      if (sink.attrs.costUsd !== undefined) span.setAttribute(ATTR.costUsd, sink.attrs.costUsd);
      return reply(true, { result: result ?? null });
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      return reply(false, { error: err instanceof ToolError || err instanceof NotAvailableError ? msg : `${call.name} failed: ${msg}` });
    }
  });
}

export interface DefaultBackendOptions {
  cacheDir?: string;
  reportsDir?: string;
  /** What `run_replays` needs: the repo under review, plus optional overrides (setups root, work root, harness). */
  replay?: Omit<ReplayRunnerDeps, "cacheDir">;
}

/**
 * The backend over the modules that exist today: ingest (fetch → parse → identify) and the observational
 * review in reports/<slug>/, and run_replays over src/replay/run.ts. The rest are not wired yet and report so.
 */
export function defaultBackend(opts: DefaultBackendOptions = {}): ToolBackend {
  const cacheDir = resolve(opts.cacheDir ?? ".roster/cache");
  const reportsDir = resolve(opts.reportsDir ?? "reports");
  const readJson = <T>(repo: string, file: string): T | null => {
    const p = join(reportsDir, reviewSlug(repo), file);
    return existsSync(p) ? (JSON.parse(readFileSync(p, "utf8")) as T) : null;
  };
  const missing = (what: string) => async (): Promise<never> => {
    throw new NotAvailableError(what);
  };
  return {
    async ingestRepo({ repo }) {
      const f = await fetchCheckpoints(repo, { cacheDir });
      if (f.backend === "none") throw new ToolError("no Entire checkpoints found in this repo");
      const sessions = parseCheckpoints(f.repoPath, f.backend === "refs" ? "git-refs" : "branch");
      const counts: Record<string, number> = {};
      for (const s of sessions) {
        const id = identify(s, f.repoPath).setupId ?? "unknown";
        counts[id] = (counts[id] ?? 0) + 1;
      }
      return { backend: f.backend, head: f.headSha, sessions: sessions.length, sessions_per_setup: counts };
    },
    async getScorecard({ repo }) {
      const review = readJson<Review>(repo, "review.json");
      if (!review) throw new ToolError(`no review for ${repo}; run \`roster review ${repo} --observational\` first`);
      const sessions = readJson<Session[]>(repo, "sessions.json") ?? [];
      const outcomes = readJson<Outcome[]>(repo, "outcomes.json") ?? [];
      return { review, setups: summarizeSetups(sessions, outcomes) };
    },
    sampleTasks: missing("stratified task sampling (src/difficulty is not built); name the tasks explicitly"),
    runReplays: replayRunner({ cacheDir, ...opts.replay }),
    getReplayResults: missing("get_replay_results (src/replay is not built)"),
    rerun: missing("rerun (src/replay is not built)"),
    classifyFailures: missing("classify_failures (src/grade has no taxonomy classifier yet)"),
    gate: missing("gate (src/gate is not built)"),
    promote: missing("promote (src/act is not built)"),
    revert: missing("revert (src/act is not built)"),
  };
}

// Replay runner (DESIGN.md §"Replay at the parent commit", §"Grade"): for each (task, setup), a sandbox at the
// task's parent commit, the setup's rules, the harness, a grade in a separate copy, failure codes, one Replay row.
//
//   const replays = await runReplays({ repo, tasks, setups, workRoot, maxCostUsd: 5 });
//
// Never throws for one run going wrong: a harness error is a Replay with verdict agent_error. Runs that are not
// started (unavailable candidate, budget reached, unsupported harness) are reported through `onSkip`.

import { chmodSync, existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { homedir, tmpdir } from "node:os";
import { join, posix, resolve, sep } from "node:path";
import { runClaude } from "../harness/claude.ts";
import type { HarnessResult } from "../harness/types.ts";
import { grade, isTestFile, type GradeResult } from "../grade/index.ts";
import { classify, parseTranscript, type Transcript } from "../grade/taxonomy.ts";
import { createSandbox, destroySandbox, proveIsolation, runGit, type IsolationProof } from "../sandbox/index.ts";
import { identify } from "../identity/index.ts";
import { fetchCheckpoints } from "../ingest/fetch.ts";
import { parseCheckpoints } from "../ingest/parse.ts";
import { loadSetups, type RunnableSetup } from "../setups/registry.ts";
import { FailureCode, type Replay, type ReplayVerdict } from "../types.ts";
import type { ReplayBatch, ToolBackend } from "../agent/tools.ts";
import { planReplayTasks, type ReplayTask } from "./tasks.ts";

export interface SkippedRun {
  task: string;
  setup: string;
  reason: string;
}

export interface RunReplaysOptions {
  /** Local path of the repo the tasks come from. */
  repo: string;
  tasks: ReplayTask[];
  setups: RunnableSetup[];
  /** Sandboxes go here. Must not be under $HOME. */
  workRoot: string;
  /** Concurrent runs. Default 3. */
  parallel?: number;
  /** No new run starts once the summed cost of finished runs reaches this. */
  maxCostUsd: number;
  harness?: typeof runClaude;
  planId?: string;
  attempt?: number;
  /** Spend cap per harness run, also bounded by what is left of maxCostUsd. Default 2. */
  perRunUsd?: number;
  maxTurns?: number;
  timeoutMs?: number;
  /** Test command for grading; default: detected from the sandbox. */
  testCmd?: string;
  /** The real `claude` binary the setting-sources shim execs. Default "claude" on the child's PATH. */
  claudeBin?: string;
  keepSandboxes?: boolean;
  onSkip?: (s: SkippedRun) => void;
}

const DEFAULT_PARALLEL = 3;
const DEFAULT_PER_RUN_USD = 2;
const DEFAULT_MAX_TURNS = 30;
const DEFAULT_TIMEOUT_MS = 20 * 60_000;
export const LOCAL_RULES_NAME = "CLAUDE.local.md";
export const SETTING_SOURCES = "project,local";

/** Default work root: the OS temp dir, never $HOME. */
export function defaultWorkRoot(): string {
  return join(tmpdir(), "roster-replays");
}

function underHome(path: string): boolean {
  const home = resolve(homedir());
  const p = resolve(path);
  return p === home || p.startsWith(home + sep);
}

/**
 * The harness pins `--setting-sources project`; replays also load CLAUDE.local.md, which needs `local`.
 * This shim rewrites that one value and execs the real binary.
 */
export function writeSettingSourcesShim(dir: string, target = "claude"): string {
  mkdirSync(dir, { recursive: true });
  const path = join(dir, "claude-setting-sources");
  const q = (s: string) => `'${s.replace(/'/g, `'\\''`)}'`;
  writeFileSync(
    path,
    `#!/bin/bash
# Written by src/replay/run.ts: --setting-sources project -> ${SETTING_SOURCES}
args=(); prev=""
for a in "$@"; do
  if [ "$prev" = "--setting-sources" ] && [ "$a" = "project" ]; then a=${q(SETTING_SOURCES)}; fi
  args+=("$a"); prev="$a"
done
exec ${q(target)} "\${args[@]}"
`,
  );
  chmodSync(path, 0o755);
  return path;
}

/** Why a setup cannot run, or null when it can. */
function unavailable(setup: RunnableSetup): string | null {
  if (setup.candidate && Object.keys(setup.env).length === 0) return "unavailable";
  if (setup.harness !== "claude-code") return `unsupported harness ${setup.harness}`;
  return null;
}

/** Directories the original change touched, for the scope guard. */
function touchedDirs(repo: string, task: ReplayTask): string[] | undefined {
  try {
    const files = runGit(repo, ["diff", "--name-only", task.parentSha, task.originalSha]).split("\n").filter(Boolean);
    return [...new Set(files.map((f) => posix.dirname(f)))];
  } catch {
    return undefined;
  }
}

/**
 * The harness writes `--output-format json` (one result object), not stream-json. Both parse here; a result-only
 * transcript has no tool calls, so it carries no evidence for F2.
 */
function loadTranscript(path: string | null): { t: Transcript; hasCalls: boolean } {
  let text = "";
  try {
    if (path && existsSync(path)) text = readFileSync(path, "utf8");
  } catch {}
  let t = parseTranscript(text);
  if (t.turns === 0 && t.result === null && text.trim()) {
    try {
      const j = JSON.parse(text);
      t = parseTranscript((Array.isArray(j) ? j : [j]).map((e) => JSON.stringify(e)).join("\n"));
    } catch {}
  }
  return { t, hasCalls: t.turns > 0 };
}

function verdictOf(g: GradeResult, hasHidden: boolean): ReplayVerdict {
  if (hasHidden && !g.hiddenPass) return "hidden_tests_failed";
  if (!g.suitePass) return "suite_failed";
  if (!g.scopeOk) return "guardrail_flagged";
  return "pass";
}

const ERROR_CODE: Partial<Record<string, FailureCode>> = {
  timeout: FailureCode.F5,
  max_turns: FailureCode.F5,
  budget: FailureCode.F5,
  spawn_failed: FailureCode.F6,
  setup_failed: FailureCode.F6,
};

/** One (task, setup) run. Never throws. */
async function runOne(
  o: RunReplaysOptions & { harness: typeof runClaude; bin: string },
  task: ReplayTask,
  setup: RunnableSetup,
  budgetUsd: number,
): Promise<Replay> {
  const attempt = o.attempt ?? 1;
  const planId = o.planId ?? "adhoc";
  const row: Replay = {
    id: `${planId}:${task.id}:${setup.id}:${attempt}`,
    plan_id: planId,
    task_session_id: task.id,
    setup_id: setup.id,
    attempt,
    isolation_proof: "",
    turns: null,
    duration_ms: null,
    cost_usd: null,
    hidden_pass: null,
    suite_pass: null,
    scope_ok: null,
    judge_equiv: null,
    failure_codes: [],
    verdict: "agent_error",
    transcript_ref: null,
    trace_url: null,
    error: null,
  };
  const fail = (code: FailureCode, why: string): Replay => {
    row.failure_codes = [code];
    row.error = why;
    if (!row.isolation_proof) row.isolation_proof = JSON.stringify({ ok: false, checks: [], error: why });
    return row;
  };

  let sandboxPath: string | null = null;
  try {
    const sb = await createSandbox(o.repo, task.parentSha, { root: o.workRoot });
    sandboxPath = sb.path;
    const proof: IsolationProof = await proveIsolation(sb.path, o.repo, task.parentSha);
    row.isolation_proof = JSON.stringify(proof);
    if (!proof.ok) return fail(FailureCode.F6, "isolation proof failed");

    // Rules in, committed as `setup:` so neither the agent's diff nor the grade sees them.
    writeFileSync(join(sb.path, "CLAUDE.md"), readFileSync(setup.rulesPath, "utf8"));
    const ruleFiles = ["CLAUDE.md"];
    if (setup.extraRulesPath) {
      writeFileSync(join(sb.path, LOCAL_RULES_NAME), readFileSync(setup.extraRulesPath, "utf8"));
      ruleFiles.push(LOCAL_RULES_NAME);
    }
    runGit(sb.path, ["add", "-f", "--", ...ruleFiles]);
    // --allow-empty: the repo's own CLAUDE.md may already equal the setup's rules (replaying this repo's own tasks).
    runGit(sb.path, [
      "-c",
      "commit.gpgsign=false",
      "commit",
      "-q",
      "--allow-empty",
      "-m",
      `setup: ${ruleFiles.join(" + ")} for ${setup.id}`,
    ]);
    const rulesSha = runGit(sb.path, ["rev-parse", "HEAD"]);

    let res: HarnessResult | null = null;
    let harnessError: string | null = null;
    try {
      res = await o.harness({
        sandboxPath: sb.path,
        prompt: task.prompt,
        model: setup.model,
        rulesFile: setup.rulesPath,
        maxTurns: o.maxTurns ?? DEFAULT_MAX_TURNS,
        timeoutMs: o.timeoutMs ?? DEFAULT_TIMEOUT_MS,
        budgetUsd,
        env: setup.env,
        bin: o.bin,
      });
    } catch (e) {
      harnessError = e instanceof Error ? e.message : String(e);
    }
    if (!res) return fail(FailureCode.F6, `harness threw: ${harnessError}`);

    row.turns = res.turns;
    row.duration_ms = res.durationMs;
    row.cost_usd = res.costUsd;
    row.transcript_ref = res.transcriptPath;
    const { t, hasCalls } = loadTranscript(res.transcriptPath);

    if (res.isError) {
      row.error = res.errorKind ?? "agent_error";
      const codes = new Set(classify({ verdict: "agent_error" }, null, t).map((c) => c.code));
      const forced = res.errorKind ? ERROR_CODE[res.errorKind] : undefined;
      if (forced === FailureCode.F6) codes.clear();
      if (forced) codes.add(forced);
      if (!hasCalls) codes.delete(FailureCode.F2);
      // A result-only transcript of an errored run is not a kill: drop the "no result event" F5 unless forced.
      if (t.result === null && forced !== FailureCode.F5 && !hasCalls) codes.delete(FailureCode.F5);
      row.failure_codes = Object.values(FailureCode).filter((c) => codes.has(c));
      return row;
    }

    // The agent's base is the setup commit (the harness's own when it made one).
    const base = res.setupSha ?? rulesSha;
    runGit(sb.path, ["add", "-A"]);
    const changed = runGit(sb.path, ["diff", "--cached", "--name-only", base]).split("\n").filter(Boolean);
    let g: GradeResult | null = null;
    if (changed.length === 0) row.verdict = "no_changes";
    else {
      const preexistingTests = runGit(sb.path, ["ls-tree", "-r", "--name-only", base]).split("\n").filter(isTestFile);
      g = await grade({
        sandbox: { path: sb.path, baseSha: base },
        hidden: task.hiddenTests,
        testCmd: o.testCmd,
        preexistingTests,
        touchedDirs: touchedDirs(o.repo, task),
      });
      const hasHidden = task.hiddenTests.length > 0;
      row.hidden_pass = hasHidden ? g.hiddenPass : null;
      row.suite_pass = g.suitePass;
      row.scope_ok = g.scopeOk;
      row.verdict = verdictOf(g, hasHidden);
    }
    // The run finished without error, so a missing result event is not a kill.
    const result = t.result ?? { subtype: "success", isError: false, numTurns: res.turns, terminalReason: res.stopReason };
    const codes = classify({ verdict: row.verdict }, g, { ...t, result }).map((c) => c.code);
    row.failure_codes = hasCalls ? codes : codes.filter((c) => c !== FailureCode.F2);
    return row;
  } catch (e) {
    // Sandbox, rules or grading broke: the environment, not the agent.
    row.verdict = "agent_error";
    row.hidden_pass = row.suite_pass = row.scope_ok = null;
    return fail(FailureCode.F6, e instanceof Error ? e.message : String(e));
  } finally {
    if (sandboxPath && !o.keepSandboxes) await destroySandbox(sandboxPath);
  }
}

export interface ReplayRunnerDeps {
  /** The repo under review (git URL or local path), as given to `roster run`. */
  repo?: string;
  cacheDir: string;
  /** Where setups/ lives. Default: the working directory. */
  setupsRoot?: string;
  env?: Record<string, string | undefined>;
  workRoot?: string;
  parallel?: number;
  harness?: typeof runClaude;
  testCmd?: string;
}

/** The coordinator's `runReplays` dependency: resolves task and setup ids, then runs them. */
export function replayRunner(deps: ReplayRunnerDeps): ToolBackend["runReplays"] {
  return async ({ plan_id, tasks: taskIds, setups: setupIds, max_cost_usd }) => {
    if (!deps.repo) throw new Error("no repo configured for replays");
    const f = await fetchCheckpoints(deps.repo, { cacheDir: deps.cacheDir });
    if (f.backend === "none") throw new Error("no Entire checkpoints found in this repo");
    const sessions = parseCheckpoints(f.repoPath, f.backend === "refs" ? "git-refs" : "branch").map((s) => ({
      ...s,
      setup_id: identify(s, f.repoPath).setupId,
    }));
    const planned = new Map(planReplayTasks(f.repoPath, sessions, []).tasks.map((t) => [t.id, t]));
    const missingTasks = taskIds.filter((t) => !planned.has(t));
    if (missingTasks.length) throw new Error(`no replayable task for session(s) ${missingTasks.join(", ")}`);
    const known = new Map(loadSetups(deps.setupsRoot ?? process.cwd(), deps.env ?? process.env).map((s) => [s.id, s]));
    const missingSetups = setupIds.filter((s) => !known.has(s));
    if (missingSetups.length) throw new Error(`unknown setup(s) ${missingSetups.join(", ")}`);

    const skipped: SkippedRun[] = [];
    const replays = await runReplays({
      repo: f.repoPath,
      tasks: taskIds.map((t) => planned.get(t)!),
      setups: setupIds.map((s) => known.get(s)!),
      workRoot: deps.workRoot ?? defaultWorkRoot(),
      parallel: deps.parallel,
      maxCostUsd: max_cost_usd,
      harness: deps.harness,
      testCmd: deps.testCmd,
      planId: plan_id,
      onSkip: (s) => skipped.push(s),
    });
    const cost_usd = replays.reduce((s, r) => s + (r.cost_usd ?? 0), 0);
    return { replays, cost_usd, skipped } as ReplayBatch;
  };
}

export async function runReplays(opts: RunReplaysOptions): Promise<Replay[]> {
  const workRoot = resolve(opts.workRoot);
  if (underHome(workRoot)) throw new Error(`workRoot ${workRoot} is under $HOME; replays must run outside it`);
  mkdirSync(workRoot, { recursive: true });
  const bin = writeSettingSourcesShim(join(workRoot, "bin"), opts.claudeBin);
  const o = { ...opts, workRoot, harness: opts.harness ?? runClaude, bin };
  const skip = (task: string, setup: string, reason: string) => opts.onSkip?.({ task, setup, reason });

  const queue: Array<{ task: ReplayTask; setup: RunnableSetup; order: number }> = [];
  for (const task of opts.tasks) {
    for (const setup of opts.setups) {
      const why = unavailable(setup);
      if (why) skip(task.id, setup.id, why);
      else queue.push({ task, setup, order: queue.length });
    }
  }

  const out: Array<{ order: number; replay: Replay }> = [];
  let spent = 0;
  let next = 0;
  const worker = async () => {
    while (next < queue.length) {
      const job = queue[next++]!;
      const left = opts.maxCostUsd - spent;
      if (left <= 0) {
        skip(job.task.id, job.setup.id, `budget: spent $${spent.toFixed(4)} of $${opts.maxCostUsd}`);
        continue;
      }
      const replay = await runOne(o, job.task, job.setup, Math.min(opts.perRunUsd ?? DEFAULT_PER_RUN_USD, left));
      spent += replay.cost_usd ?? 0;
      out.push({ order: job.order, replay });
    }
  };
  const n = Math.max(1, Math.floor(opts.parallel ?? DEFAULT_PARALLEL));
  await Promise.all(Array.from({ length: Math.min(n, queue.length) }, worker));
  return out.sort((a, b) => a.order - b.order).map((x) => x.replay);
}
// Replayable tasks from recorded sessions (DESIGN.md §"Plan (coordinator)", §"Replay at the parent commit"):
// what was asked, the commit to start from, and the tests the team kept.

import { hiddenTestsForCommits } from "../grade/hidden.ts";
import { runGit } from "../sandbox/index.ts";
import type { Outcome, Session } from "../types.ts";

export interface ReplayTask {
  /** Same as the session id. */
  id: string;
  sessionId: string;
  setupId: string | null;
  /** The `roster setup=… task=…` tag text that led the first prompt, if any. */
  tag: string | null;
  prompt: string;
  /** First parent of the session's earliest linked commit. */
  parentSha: string;
  /** The session's latest linked commit. */
  originalSha: string;
  hiddenTests: { path: string; content: string }[];
  userPrompts: number;
  tercile: 1 | 2 | 3 | null;
  track: "tests" | "judge-only" | "none";
  reason: string;
}

export interface SkippedSession {
  sessionId: string;
  reason: string;
}

/** Most user prompts a session may have and still be eligible for replay. */
const MAX_PROMPTS = 2;
const TAG_LINE = /^\s*\[(roster setup=[^\]]*)\][ \t]*\r?\n?/;
const BRANCH_REFS = ["refs/heads/entire/checkpoints/v1", "refs/remotes/origin/entire/checkpoints/v1"];

function tryGit(repo: string, args: string[]): string | null {
  try {
    return runGit(repo, args);
  } catch {
    return null;
  }
}

/** Splits a leading roster tag off a prompt. */
export function stripTag(prompt: string): { tag: string | null; prompt: string } {
  const m = TAG_LINE.exec(prompt);
  return m ? { tag: m[1]!, prompt: prompt.slice(m[0].length).trim() } : { tag: null, prompt: prompt.trim() };
}

interface Link {
  sha: string;
  time: number;
  importStrategy: boolean;
}

/** Session id → commits whose checkpoint trailer names a checkpoint holding that session. */
function linkIndex(repo: string): Map<string, Link[]> {
  const index = new Map<string, Link[]>();
  const log = tryGit(repo, [
    "log",
    "--all",
    "--format=%H%x1f%ct%x1f%(trailers:key=Entire-Checkpoint,valueonly,separator=%x2c)%x1e",
  ]);
  const ref = BRANCH_REFS.find((r) => tryGit(repo, ["rev-parse", "--verify", "-q", r]) !== null);
  if (!log || !ref) return index;
  const show = (path: string): any => {
    const out = tryGit(repo, ["show", `${ref}:${path}`]);
    try {
      return out === null ? null : JSON.parse(out);
    } catch {
      return null;
    }
  };
  for (const rec of log.split("\x1e")) {
    const [sha, ct, ids] = rec.trim().split("\x1f");
    if (!sha || !ids) continue;
    for (const id of ids.split(",").map((s) => s.trim()).filter(Boolean)) {
      const dir = `${id.slice(0, 2)}/${id.slice(2)}`;
      const root = show(`${dir}/metadata.json`);
      if (!root) continue;
      const n = Array.isArray(root.sessions) ? root.sessions.length : 0;
      for (let i = 0; i < n; i++) {
        const sid = show(`${dir}/${i}/metadata.json`)?.session_id;
        if (typeof sid !== "string") continue;
        (index.get(sid) ?? index.set(sid, []).get(sid)!).push({
          sha,
          time: Number(ct),
          importStrategy: root.strategy === "import",
        });
      }
    }
  }
  return index;
}

/** Tasks plus the sessions that could not become one, each with its reason. */
export function planReplayTasks(
  repo: string,
  sessions: Session[],
  outcomes: Outcome[],
): { tasks: ReplayTask[]; skipped: SkippedSession[] } {
  const tercile = new Map(outcomes.map((o) => [o.session_id, o.tercile]));
  const links = linkIndex(repo);
  const tasks: (ReplayTask & { time: number })[] = [];
  const skipped: SkippedSession[] = [];
  const seen = new Set<string>();

  for (const s of sessions) {
    if (seen.has(s.id)) continue;
    seen.add(s.id);
    const mine = sessions.filter((x) => x.id === s.id);
    const found = new Map<string, Link>((links.get(s.id) ?? []).map((l) => [l.sha, l]));
    for (const x of mine) {
      if (x.commit_sha && !found.has(x.commit_sha)) {
        const t = tryGit(repo, ["show", "-s", "--format=%ct", x.commit_sha]);
        if (t !== null) found.set(x.commit_sha, { sha: x.commit_sha, time: Number(t), importStrategy: false });
      }
    }
    const commits = [...found.values()].sort((a, b) => a.time - b.time || a.sha.localeCompare(b.sha));
    if (commits.length === 0) {
      skipped.push({ sessionId: s.id, reason: "no linked commit" });
      continue;
    }
    const earliest = commits[0]!;
    const latest = commits.at(-1)!;
    const parentSha = tryGit(repo, ["rev-parse", `${earliest.sha}^1`]);
    if (!parentSha) {
      skipped.push({ sessionId: s.id, reason: `earliest commit ${earliest.sha.slice(0, 7)} has no parent` });
      continue;
    }

    const userPrompts = Math.max(...mine.map((x) => x.n_user_prompts));
    const tests = hiddenTestsForCommits(repo, commits.map((c) => c.sha));
    let track: ReplayTask["track"];
    let reason: string;
    if (commits.some((c) => c.importStrategy)) [track, reason] = ["none", "imported history, not captured live"];
    else if (userPrompts > MAX_PROMPTS) [track, reason] = ["none", `${userPrompts} user prompts (more than ${MAX_PROMPTS})`];
    else if (tests.length === 0) [track, reason] = ["judge-only", "no hidden tests in the original change"];
    else [track, reason] = ["tests", `${tests.length} hidden test file(s)`];

    const { tag, prompt } = stripTag(s.first_prompt);
    tasks.push({
      id: s.id,
      sessionId: s.id,
      setupId: s.setup_id,
      tag,
      prompt,
      parentSha,
      originalSha: latest.sha,
      hiddenTests: tests,
      userPrompts,
      tercile: tercile.get(s.id) ?? null,
      track,
      reason,
      time: latest.time,
    });
  }
  tasks.sort((a, b) => a.time - b.time || a.originalSha.localeCompare(b.originalSha) || a.id.localeCompare(b.id));
  return { tasks: tasks.map(({ time: _t, ...t }) => t), skipped };
}

export function buildReplayTasks(repo: string, sessions: Session[], outcomes: Outcome[]): ReplayTask[] {
  return planReplayTasks(repo, sessions, outcomes).tasks;
}

// Deterministic promotion gate (DESIGN.md §"Gate"). Pure code: the coordinator can't override it.
//
// promote(candidate) iff, on the replay set (incumbent replayed as the control):
//   hidden_pass(candidate) ≥ hidden_pass(incumbent)
//   ∧ regressions == 0          # incumbent passed, candidate failed, after reruns
//   ∧ scope_violations == 0
//   ∧ cost(candidate) ≤ budget
// ties → cheaper wins; still tied → keep incumbent
//
// Conventions:
// - Results are Replay rows; several rows for one task are reruns (`attempt`).
// - Attempts carrying F6 (environment error) are excluded. A task with no usable attempt on
//   either side is excluded from the comparison (it is resampled upstream).
// - A side passes a task when a strict majority of its usable attempts have hidden_pass === true.
//   A 1–1 split is not a majority, so it counts as not passing.
// - A task the incumbent has but the candidate lacks counts as a candidate failure.
// - cost(setup) = sum over compared tasks of the mean cost of that task's usable attempts, so
//   reruns don't penalise a setup. Any unknown (null) cost makes the cost unknown.

import { FailureCode } from "../types.ts";
import type { GateVerdict, Replay } from "../types.ts";

/** Max attempts per task and side (DESIGN.md §"Grade" step 6). */
export const MAX_ATTEMPTS = 3;

export type GateResults = Pick<
  Replay,
  "task_session_id" | "attempt" | "hidden_pass" | "scope_ok" | "cost_usd" | "failure_codes"
>[];

export interface GateOptions {
  /** Cost cap for the candidate, in USD. */
  budget: number;
}

/** How a hidden-pass tie was resolved: no tie, candidate cheaper, or kept incumbent. */
export type GateTie = "none" | "cheaper" | "incumbent";

export interface GateResult {
  verdict: GateVerdict;
  reasons: string[];
  /** Task ids the incumbent passed and the candidate failed, after reruns. */
  regressions: string[];
  ties: GateTie;
  hidden_pass: { incumbent: number; candidate: number };
  /** Task ids where any usable candidate attempt had scope_ok === false. */
  scope_violations: string[];
  cost: { incumbent: number | null; candidate: number | null };
  /** Task ids excluded because one side had no usable attempt (all F6). */
  excluded: string[];
}

interface Tally {
  attempts: number;
  passes: number;
  scopeViolation: boolean;
  /** Mean usable-attempt cost; null when any cost is unknown. */
  cost: number | null;
}

function usable(r: GateResults[number]): boolean {
  return !r.failure_codes.includes(FailureCode.F6);
}

function tally(results: GateResults): Map<string, Tally> {
  const groups = new Map<string, GateResults>();
  for (const r of results) {
    if (!usable(r)) {
      if (!groups.has(r.task_session_id)) groups.set(r.task_session_id, []);
      continue;
    }
    const g = groups.get(r.task_session_id);
    if (g) g.push(r);
    else groups.set(r.task_session_id, [r]);
  }
  const out = new Map<string, Tally>();
  for (const [task, rs] of groups) {
    let sum = 0;
    let known = true;
    for (const r of rs) {
      if (r.cost_usd === null) known = false;
      else sum += r.cost_usd;
    }
    out.set(task, {
      attempts: rs.length,
      passes: rs.filter((r) => r.hidden_pass === true).length,
      scopeViolation: rs.some((r) => r.scope_ok === false),
      cost: known && rs.length > 0 ? sum / rs.length : null,
    });
  }
  return out;
}

function passes(t: Tally | undefined): boolean {
  return t !== undefined && t.passes * 2 > t.attempts;
}

/** Majority is settled once no further attempt (up to MAX_ATTEMPTS) could flip it. */
function settled(t: Tally | undefined): boolean {
  if (!t || t.attempts === 0) return false; // missing: needs a first attempt
  const remaining = Math.max(0, MAX_ATTEMPTS - t.attempts);
  const fails = t.attempts - t.passes;
  return remaining === 0 || t.passes > fails + remaining || fails >= t.passes + remaining;
}

export interface Discordant {
  task_session_id: string;
  /** Which sides need another attempt. */
  rerun: ("incumbent" | "candidate")[];
}

/**
 * Tasks where the two setups split and at least one side's majority is not yet settled within
 * k = MAX_ATTEMPTS. Run one more attempt on each listed side, then call again until empty.
 */
export function discordant(incumbent: GateResults, candidate: GateResults): Discordant[] {
  const inc = tally(incumbent);
  const cand = tally(candidate);
  const tasks = [...new Set([...inc.keys(), ...cand.keys()])].sort();
  const out: Discordant[] = [];
  for (const task of tasks) {
    const i = inc.get(task);
    const c = cand.get(task);
    // All-F6 on either side: the task is excluded and resampled, not rerun.
    if (i?.attempts === 0 || c?.attempts === 0) continue;
    if (passes(i) === passes(c)) continue;
    const rerun: Discordant["rerun"] = [];
    if (!settled(i)) rerun.push("incumbent");
    if (!settled(c)) rerun.push("candidate");
    if (rerun.length > 0) out.push({ task_session_id: task, rerun });
  }
  return out;
}

function totalCost(t: Map<string, Tally>, tasks: string[]): number | null {
  let sum = 0;
  for (const task of tasks) {
    const c = t.get(task)?.cost;
    if (c === null || c === undefined) return null;
    sum += c;
  }
  return sum;
}

function fmt(n: number | null): string {
  return n === null ? "unknown" : `$${n.toFixed(4)}`;
}

export function gate(incumbentResults: GateResults, candidateResults: GateResults, opts: GateOptions): GateResult {
  const inc = tally(incumbentResults);
  const cand = tally(candidateResults);

  const excluded: string[] = [];
  const tasks: string[] = [];
  for (const task of [...new Set([...inc.keys(), ...cand.keys()])].sort()) {
    const i = inc.get(task);
    const c = cand.get(task);
    const allF6 = (t: Tally | undefined) => t !== undefined && t.attempts === 0;
    if (allF6(i) || allF6(c)) excluded.push(task);
    // Tasks only the candidate ran are not part of the incumbent's replay set.
    else if (i) tasks.push(task);
  }

  const hidden = {
    incumbent: tasks.filter((t) => passes(inc.get(t))).length,
    candidate: tasks.filter((t) => passes(cand.get(t))).length,
  };
  const regressions = tasks.filter((t) => passes(inc.get(t)) && !passes(cand.get(t)));
  const scope_violations = tasks.filter((t) => cand.get(t)?.scopeViolation === true);
  const missing = tasks.filter((t) => !cand.has(t));
  const cost = { incumbent: totalCost(inc, tasks), candidate: missing.length ? null : totalCost(cand, tasks) };

  const reasons: string[] = [];
  if (tasks.length === 0) reasons.push("empty replay set: no comparable tasks");
  if (hidden.candidate < hidden.incumbent)
    reasons.push(`hidden_pass ${hidden.candidate} < incumbent ${hidden.incumbent}`);
  if (regressions.length > 0) reasons.push(`${regressions.length} regression(s) after reruns: ${regressions.join(", ")}`);
  if (scope_violations.length > 0)
    reasons.push(`${scope_violations.length} scope violation(s): ${scope_violations.join(", ")}`);
  if (missing.length > 0) reasons.push(`candidate missing results for: ${missing.join(", ")}`);
  if (cost.candidate === null) reasons.push("candidate cost unknown; cannot verify budget");
  else if (cost.candidate > opts.budget) reasons.push(`cost ${fmt(cost.candidate)} > budget ${fmt(opts.budget)}`);

  let ties: GateTie = "none";
  if (reasons.length === 0 && hidden.candidate === hidden.incumbent) {
    // Rules passed with equal hidden_pass: candidate must be strictly cheaper.
    if (cost.incumbent !== null && cost.candidate !== null && cost.candidate < cost.incumbent) {
      ties = "cheaper";
      reasons.push(`tie on hidden_pass ${hidden.candidate}; candidate cheaper ${fmt(cost.candidate)} < ${fmt(cost.incumbent)}`);
      return { verdict: "promote", reasons, regressions, ties, hidden_pass: hidden, scope_violations, cost, excluded };
    }
    ties = "incumbent";
    reasons.push(
      `tie on hidden_pass ${hidden.candidate}; candidate not cheaper (${fmt(cost.candidate)} vs ${fmt(cost.incumbent)}), keep incumbent`,
    );
    return { verdict: "reject", reasons, regressions, ties, hidden_pass: hidden, scope_violations, cost, excluded };
  }

  if (reasons.length > 0)
    return { verdict: "reject", reasons, regressions, ties, hidden_pass: hidden, scope_violations, cost, excluded };
  reasons.push(`hidden_pass ${hidden.candidate} > incumbent ${hidden.incumbent}, 0 regressions, within budget`);
  return { verdict: "promote", reasons, regressions, ties, hidden_pass: hidden, scope_violations, cost, excluded };
}
// Setup registry (DESIGN.md §"Setups", §"Candidate generation").
//
//   const setups = loadSetups(repoRoot, process.env);   // sorted by id
//
// Reads setups/*.json (candidate: false) and setups/candidates/*.json (candidate: true). Never throws on a
// missing provider variable: that candidate is returned with env {} and an "(unavailable: <VAR> not set)" label.
// Only variable names are ever reported, never values.

import { existsSync, readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { providerEnv } from "../harness/provider";

export interface RunnableSetup {
  id: string;
  label: string;
  harness: "claude-code" | "codex";
  model: string;
  rulesPath: string;
  extraRulesPath: string | null;
  env: Record<string, string>;
  candidate: boolean;
}

interface SetupFile {
  id: string;
  label?: string;
  harness: "claude-code" | "codex";
  model: string;
  rules: string;
  append_rules?: string;
  env?: Record<string, string>;
}

const REF = /\$\{([A-Za-z_][A-Za-z0-9_]*)\}/g;

function readDir(dir: string, candidate: boolean): Array<{ file: SetupFile; candidate: boolean }> {
  if (!existsSync(dir)) return [];
  return readdirSync(dir)
    .filter((f) => f.endsWith(".json"))
    .sort()
    .map((f) => ({ file: JSON.parse(readFileSync(join(dir, f), "utf8")) as SetupFile, candidate }));
}

function missingVars(file: SetupFile, env: Record<string, string | undefined>): string[] {
  const missing: string[] = [];
  for (const raw of Object.values(file.env ?? {})) {
    for (const m of raw.matchAll(REF)) {
      const name = m[1]!;
      const v = env[name];
      if ((v === undefined || v === "") && !missing.includes(name)) missing.push(name);
    }
  }
  return missing;
}

export function loadSetups(root: string, env: Record<string, string | undefined>): RunnableSetup[] {
  const entries = [...readDir(join(root, "setups"), false), ...readDir(join(root, "setups", "candidates"), true)];
  const out: RunnableSetup[] = entries.map(({ file, candidate }) => {
    const missing = missingVars(file, env);
    let label = file.label ?? file.id;
    let resolved: Record<string, string> = {};
    if (missing.length > 0) {
      label += ` (unavailable: ${missing.join(", ")} not set)`;
    } else {
      try {
        resolved = providerEnv(file, env);
      } catch {
        label += " (unavailable: provider env could not be resolved)";
      }
    }
    return {
      id: file.id,
      label,
      harness: file.harness,
      model: file.model,
      rulesPath: join(root, file.rules),
      extraRulesPath: file.append_rules ? join(root, file.append_rules) : null,
      env: resolved,
      candidate,
    };
  });
  return out.sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
}

// Failure taxonomy classifier (DESIGN.md §"Failure taxonomy"). Explains why a failed replay failed:
// F1–F7 with evidence strings, from the run's tool calls (stream-json transcript) and its grade.
//
//   const failures = classify(replay, grade, parseTranscript(streamJson));
//
// A passing replay has no failures, so classify returns [] for it. An F6 (environment) failure
// excludes the task, so it is returned alone: the other codes say nothing about the agent then.

import { FailureCode } from "../types.ts";
import type { Replay } from "../types.ts";
import type { GradeResult } from "./index.ts";

export interface ToolCall {
  id: string;
  /** 1-based index of the assistant message that made the call. */
  turn: number;
  name: string;
  input: Record<string, unknown>;
}

export interface ToolResult {
  toolUseId: string;
  isError: boolean;
  text: string;
}

/** The harness's closing `result` event. */
export interface RunResult {
  subtype: string;
  isError: boolean;
  numTurns: number | null;
  terminalReason: string | null;
}

export interface Transcript {
  calls: ToolCall[];
  results: Map<string, ToolResult>;
  /** Text of the last assistant message, "" when it had none. */
  finalText: string;
  /** Distinct assistant messages. */
  turns: number;
  /** null when the run never emitted a result event (killed mid-run). */
  result: RunResult | null;
}

export interface Classified {
  code: FailureCode;
  evidence: string[];
}

const EDIT_TOOLS = new Set(["Edit", "Write", "MultiEdit", "NotebookEdit"]);
const INSTALL_OR_BUILD =
  /\b(bun|npm|pnpm|yarn)\s+(install|i|add|ci)\b|\b(bun|npm|pnpm|yarn)\s+run\s+build\b|\bbun\s+build\b|\btsc\b|\bpip3?\s+install\b|\bgo\s+(mod\s+download|build)\b/;
const TEST_RUN = /\b(bun\s+test|(npm|pnpm|yarn)\s+(run\s+)?test|pytest|go\s+test|cargo\s+test)\b/;
const ERROR_TEXT = /\b(ERR!|error:|E404|ENOTFOUND|EAI_AGAIN|Could not resolve|failed to)\b/i;
const STOP_TEXT = /\b(cannot|can't|unable to|not able to|should i|would you like|do you want)\b|\?\s*$/i;
const LOOP_MIN_REPEATS = 3;

const str = (v: unknown) => (typeof v === "string" ? v : "");

function blockText(content: unknown): string {
  if (typeof content === "string") return content;
  if (!Array.isArray(content)) return "";
  return content
    .filter((b) => b?.type === "text")
    .map((b) => str(b.text))
    .join("\n");
}

/**
 * Parses a `claude -p --output-format stream-json --verbose` transcript. A line cut off by a kill is
 * skipped, so a truncated run still classifies.
 */
export function parseTranscript(jsonl: string): Transcript {
  const calls: ToolCall[] = [];
  const results = new Map<string, ToolResult>();
  const seenMessages = new Set<string>();
  let turns = 0;
  let finalText = "";
  let result: RunResult | null = null;
  for (const line of jsonl.split("\n")) {
    if (line.trim() === "") continue;
    let ev: any;
    try {
      ev = JSON.parse(line);
    } catch {
      continue;
    }
    if (ev?.type === "assistant") {
      const msgId = str(ev.message?.id) || `anon-${turns + 1}`;
      if (!seenMessages.has(msgId)) {
        seenMessages.add(msgId);
        turns++;
      }
      const blocks: any[] = Array.isArray(ev.message?.content) ? ev.message.content : [];
      finalText = blockText(blocks);
      for (const b of blocks) {
        if (b?.type === "tool_use") calls.push({ id: str(b.id), turn: turns, name: str(b.name), input: b.input ?? {} });
      }
    } else if (ev?.type === "user") {
      const blocks: any[] = Array.isArray(ev.message?.content) ? ev.message.content : [];
      for (const b of blocks) {
        if (b?.type === "tool_result") {
          const toolUseId = str(b.tool_use_id);
          results.set(toolUseId, { toolUseId, isError: b.is_error === true, text: blockText(b.content) });
        }
      }
    } else if (ev?.type === "result") {
      result = {
        subtype: str(ev.subtype),
        isError: ev.is_error === true,
        numTurns: typeof ev.num_turns === "number" ? ev.num_turns : null,
        terminalReason: str(ev.terminal_reason ?? ev.stop_reason) || null,
      };
    }
  }
  return { calls, results, finalText, turns, result };
}

const isBash = (c: ToolCall) => c.name === "Bash" && typeof c.input.command === "string";
const bashCmd = (c: ToolCall) => str(c.input.command);
const editPath = (c: ToolCall) => str(c.input.file_path) || str(c.input.notebook_path);
/** Matches a grader path (repo-relative) against a tool call path (absolute inside the sandbox, or relative). */
const samePath = (called: string, repoPath: string) => called === repoPath || called.endsWith(`/${repoPath}`);
const firstLine = (s: string) => s.split("\n").find((l) => l.trim() !== "")?.trim().slice(0, 160) ?? "";
const snippet = (s: string) => `"${s.replace(/\s+/g, " ").trim().slice(0, 120)}"`;

/** The turn of the first edit call that touched `repoPath`, or undefined. */
function editTurn(t: Transcript, repoPath: string): number | undefined {
  return t.calls.find((c) => EDIT_TOOLS.has(c.name) && samePath(editPath(c), repoPath))?.turn;
}

/** Classifies a replay. Returns codes in F1..F7 order, each with the evidence that supports it. */
export function classify(replay: Pick<Replay, "verdict">, grade: GradeResult | null, transcript: Transcript): Classified[] {
  if (replay.verdict === "pass") return [];
  const found = new Map<FailureCode, string[]>();
  const add = (code: FailureCode, ...ev: string[]) => found.set(code, [...(found.get(code) ?? []), ...ev]);
  const t = transcript;

  // F6 first: an install or build that failed before the agent's first edit excludes the task.
  const firstEdit = t.calls.findIndex((c) => EDIT_TOOLS.has(c.name));
  const envFail = t.calls.find((c, i) => {
    if (firstEdit >= 0 && i >= firstEdit) return false;
    if (!isBash(c) || !INSTALL_OR_BUILD.test(bashCmd(c))) return false;
    const r = t.results.get(c.id);
    return r !== undefined && (r.isError || ERROR_TEXT.test(r.text));
  });
  if (envFail) {
    const r = t.results.get(envFail.id);
    add(FailureCode.F6, `\`${bashCmd(envFail)}\` failed at turn ${envFail.turn} before any edit: ${firstLine(r?.text ?? "")}`);
    return [{ code: FailureCode.F6, evidence: found.get(FailureCode.F6)! }];
  }

  // F1: the grader found a pre-existing test file deleted or changed (not just appended to).
  for (const v of grade?.violations ?? []) {
    if (v.code !== FailureCode.F1) continue;
    const turn = editTurn(t, v.path);
    add(FailureCode.F1, turn === undefined ? `${v.path}: ${v.detail}` : `edited ${v.path} at turn ${turn} (${v.detail})`);
  }

  // F2: no test command was ever run.
  if (!t.calls.some((c) => isBash(c) && TEST_RUN.test(bashCmd(c)))) {
    add(FailureCode.F2, `no test command in ${t.calls.length} tool calls`);
  }

  // F3: the full suite failed on the agent's tree.
  if (grade && !grade.suitePass) add(FailureCode.F3, "full suite failed on the agent's tree");

  // F4: the run ended normally, the hidden acceptance tests failed, and the last message is a stop or a question.
  if (t.result && !t.result.isError && t.result.subtype === "success" && grade && !grade.hiddenPass && STOP_TEXT.test(t.finalText)) {
    add(FailureCode.F4, `stopped at turn ${t.turns} with hidden tests failing: ${snippet(t.finalText)}`);
  }

  // F5: turn cap, spend cap, timeout (no result event), or a loop of identical tool calls.
  if (t.result === null) add(FailureCode.F5, "no result event: the run was killed (timeout)");
  else if (t.result.subtype === "error_max_turns") add(FailureCode.F5, `hit turn cap after ${t.result.numTurns ?? t.turns} turns`);
  else if (/budget/i.test(t.result.subtype)) add(FailureCode.F5, `hit spend cap (${t.result.subtype})`);
  for (let i = 0; i < t.calls.length; ) {
    const key = (c: ToolCall) => `${c.name} ${JSON.stringify(c.input)}`;
    let j = i + 1;
    while (j < t.calls.length && key(t.calls[j]!) === key(t.calls[i]!)) j++;
    if (j - i >= LOOP_MIN_REPEATS) {
      const c = t.calls[i]!;
      add(FailureCode.F5, `repeated ${c.name} ${j - i}x from turn ${c.turn} to turn ${t.calls[j - 1]!.turn}`);
    }
    i = j;
  }

  // F7: the grader found edits outside the directories the original change touched.
  for (const v of grade?.violations ?? []) {
    if (v.code !== FailureCode.F7) continue;
    const turn = editTurn(t, v.path);
    add(FailureCode.F7, turn === undefined ? `${v.path}: ${v.detail}` : `edited ${v.path} at turn ${turn} (${v.detail})`);
  }

  return Object.values(FailureCode)
    .filter((code) => found.has(code))
    .map((code) => ({ code, evidence: found.get(code)! }));
}
// `roster run <repo> --budget <usd>`: the coordinator agent on DeepSeek, over the tool backend
// (DESIGN.md §"Coordinator tools"). One WORKFLOW span per run; the coordinator adds AGENT and TOOL spans.
import { join, resolve } from "node:path";
import type { Command } from "../cli.ts";
import { deepseekClient } from "../llm/client.ts";
import { flushObs, initObs, setSession, withSpan } from "../obs/index.ts";
import { repoLabel, reviewSlug } from "../review/export.ts";
import { DEFAULT_DB, newRunId, runCoordinator } from "../agent/coordinator.ts";
import { defaultBackend } from "../agent/tools.ts";
import { DEFAULT_CACHE, UsageError } from "./review.ts";

const USAGE = `usage: roster run <repo> --budget <usd> [--out <dir>] [--run-id <id>] [--db <path>] [--model <m>] [--cache <dir>]

  <repo>           a git URL or local path with Entire checkpoints
  --budget <usd>   hard stop for LLM plus replay cost (required)
  --out <dir>      where plan.json and decisions.json go (default reports/<slug>)
  --run-id <id>    resume this run from ${DEFAULT_DB}, or start it under this id
  --db <path>      state database (default ${DEFAULT_DB})
  --model <m>      coordinator model (default env ROSTER_LLM_MODEL, else deepseek-flash)
  --cache <dir>    fetch cache (default ${DEFAULT_CACHE})

Roster's own model calls go to DeepSeek; set DEEPSEEK_API_KEY in .env.`;

export interface RunArgs {
  repo: string;
  budgetUsd: number;
  out: string | undefined;
  runId: string | undefined;
  db: string;
  model: string | undefined;
  cache: string;
}

/** Parses the arguments after `run`. Throws UsageError on anything it does not accept. */
export function parseRunArgs(args: string[]): RunArgs {
  let repo: string | undefined;
  let budget: string | undefined;
  const parsed: Omit<RunArgs, "repo" | "budgetUsd"> = {
    out: undefined,
    runId: undefined,
    db: DEFAULT_DB,
    model: undefined,
    cache: DEFAULT_CACHE,
  };
  for (let i = 0; i < args.length; i++) {
    const a = args[i]!;
    const eq = a.indexOf("=");
    const name = eq === -1 ? a : a.slice(0, eq);
    const takeValue = (): string => {
      if (eq !== -1) return a.slice(eq + 1);
      const v = args[++i];
      if (v === undefined || v.startsWith("--")) throw new UsageError(`${name} needs a value`);
      return v;
    };
    if (name === "--budget") budget = takeValue();
    else if (name === "--out") parsed.out = takeValue();
    else if (name === "--run-id") parsed.runId = takeValue();
    else if (name === "--db") parsed.db = takeValue();
    else if (name === "--model") parsed.model = takeValue();
    else if (name === "--cache") parsed.cache = takeValue();
    else if (a.startsWith("-")) throw new UsageError(`unknown flag ${a}`);
    else if (repo === undefined) repo = a;
    else throw new UsageError(`unexpected argument ${a}`);
  }
  if (repo === undefined) throw new UsageError("missing <repo>");
  if (budget === undefined) throw new UsageError("--budget is required");
  const budgetUsd = Number(budget);
  if (!Number.isFinite(budgetUsd) || budgetUsd <= 0) throw new UsageError(`--budget must be a positive number, got ${budget}`);
  return { repo, budgetUsd, ...parsed };
}

/** Runs the coordinator. Exit 0 when it promoted or honestly found no better setup, 1 otherwise. */
export async function runRun(args: RunArgs): Promise<number> {
  const label = repoLabel(args.repo);
  const outDir = resolve(args.out ?? join("reports", reviewSlug(args.repo)));
  const llm = deepseekClient({ model: args.model });
  const runId = args.runId ?? newRunId(new Date());
  await initObs({ workflowName: "roster-run" });
  setSession(runId);
  try {
    const res = await withSpan("WORKFLOW", "review", { repo: label }, () =>
      runCoordinator({
        repo: args.repo,
        budgetUsd: args.budgetUsd,
        llm,
        backend: defaultBackend({ cacheDir: args.cache, replay: { repo: args.repo } }),
        outDir,
        dbPath: resolve(args.db),
        runId,
        model: args.model,
      }),
    );
    console.log(`roster run ${label} (${res.runId}${res.resumed ? ", resumed" : ""}): ${res.outcome}`);
    console.log(res.summary);
    console.log(
      `spent $${res.spentUsd.toFixed(4)} of $${args.budgetUsd} (LLM $${res.llmUsd.toFixed(4)}, replays $${res.replayUsd.toFixed(4)}) in ${res.turns} turns`,
    );
    if (res.unpricedLlmCalls > 0) {
      console.warn(`warning: ${res.unpricedLlmCalls} LLM calls have no price in src/price; their cost is not in the total`);
    }
    console.log(`wrote ${[res.planPath, res.decisionsPath].filter(Boolean).join(", ")}`);
    return res.outcome === "promoted" || res.outcome === "no_better_setup" ? 0 : 1;
  } finally {
    await flushObs();
  }
}

export const runCommand: Command = {
  name: "run",
  summary: "run the coordinator agent: plan, replay, gate (needs DEEPSEEK_API_KEY)",
  usage: USAGE,
  async run(args) {
    let parsed: RunArgs;
    try {
      parsed = parseRunArgs(args);
    } catch (err) {
      if (!(err instanceof UsageError)) throw err;
      console.error(`roster run: ${err.message}\n\n${USAGE}`);
      return 2;
    }
    return runRun(parsed);
  },
};

if (import.meta.main) {
  process.exitCode = await runCommand.run(process.argv.slice(2));
}

// The coordinator: a tool-calling loop on src/llm (DESIGN.md §"Plan (coordinator)", §"Coordinator tools", §"Recovery").
// It plans, replays, reads the gate and decides the next action until a candidate is promoted, it gives up honestly,
// or it hits budget_usd (LLM cost plus replay cost) or MAX_TURNS. Every step is appended to the `events` table in
// .roster/roster.db, and a run with the same id resumes from there.
import { Database } from "bun:sqlite";
import { mkdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { ATTR } from "../obs/attributes.ts";
import { withSpan } from "../obs/index.ts";
import type { ChatMessage, LlmClient } from "../llm/types.ts";
import type { Plan } from "../types.ts";
import { planFile, writePlanFile } from "./plan.ts";
import {
  type Decision,
  executeToolCall,
  initialState,
  planId,
  type RunState,
  TOOL_SPECS,
  type ToolBackend,
  type ToolContext,
} from "./tools.ts";

export const MAX_TURNS = 40;
export const DEFAULT_DB = ".roster/roster.db";

export const SYSTEM_PROMPT = `You are Roster's coordinator. Roster runs performance reviews for AI coding agents: it replays past tasks under the incumbent setup and candidate setups, grades them, and lets a deterministic gate decide promotion.

You decide what to try next. The gate decides what ships. Never claim a result the tools didn't return.

How to work:
- Read the scorecard, then call plan_replays with a one-paragraph rationale, the suspect setup, at most 3 candidates and at most 12 tasks.
- Replay the incumbent (as the control) and the candidates with run_replays, inspect results, rerun disagreements, and classify failures.
- Call gate for a candidate. If it promotes, call promote. If it rejects, replan with plan_replays and try the next candidate.
- If a task hits F6 (environment error), replan with a resampled task set.
- If no candidate passes, finish with outcome "no_better_setup". That is a valid result.
- The budget is a hard stop. Every tool answers with JSON; {"ok":false} means the call failed and you must not treat it as a result.`;

export type StopReason = "promoted" | "no_better_setup" | "budget" | "max_turns" | "stopped" | "llm_error";

/** Outcomes after which resuming does nothing more. */
const FINAL: ReadonlySet<StopReason> = new Set(["promoted", "no_better_setup", "stopped"]);

export interface RunResult {
  runId: string;
  outcome: StopReason;
  promoted: string | null;
  summary: string;
  turns: number;
  llmUsd: number;
  replayUsd: number;
  spentUsd: number;
  /** LLM calls src/price could not price; their cost is not in llmUsd. */
  unpricedLlmCalls: number;
  decisions: Decision[];
  planPath: string | null;
  decisionsPath: string;
  resumed: boolean;
}

export interface CoordinatorOptions {
  repo: string;
  budgetUsd: number;
  llm: LlmClient;
  backend: ToolBackend;
  /** Where plan.json and decisions.json go. */
  outDir: string;
  /** Default DEFAULT_DB. */
  dbPath?: string;
  /** Resume this run when its events exist; otherwise start it under this id. */
  runId?: string;
  reviewId?: string;
  model?: string;
  temperature?: number;
  maxTurns?: number;
  now?: () => Date;
}

interface StoredEvent {
  seq: number;
  kind: "start" | "llm" | "tool" | "note" | "end";
  payload: Record<string, unknown>;
}

/** The append-only step log plus the plans and gate_decisions tables (DESIGN.md §"Data model"). */
export class EventStore {
  readonly db: Database;

  constructor(path: string) {
    if (path !== ":memory:") mkdirSync(dirname(path), { recursive: true });
    this.db = new Database(path, { create: true });
    this.db.exec("PRAGMA journal_mode = WAL");
    this.db.exec(`CREATE TABLE IF NOT EXISTS events (
      id INTEGER PRIMARY KEY AUTOINCREMENT, run_id TEXT NOT NULL, seq INTEGER NOT NULL, kind TEXT NOT NULL,
      payload TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE (run_id, seq))`);
    this.db.exec(`CREATE TABLE IF NOT EXISTS plans (
      id TEXT PRIMARY KEY, review_id TEXT NOT NULL, json TEXT NOT NULL, rationale TEXT NOT NULL, created_at TEXT NOT NULL)`);
    this.db.exec(`CREATE TABLE IF NOT EXISTS gate_decisions (
      id TEXT PRIMARY KEY, plan_id TEXT NOT NULL, candidate TEXT NOT NULL, verdict TEXT NOT NULL,
      reasons TEXT NOT NULL, trace_url TEXT)`);
  }

  events(runId: string): StoredEvent[] {
    return this.db
      .query<{ seq: number; kind: StoredEvent["kind"]; payload: string }, [string]>(
        "SELECT seq, kind, payload FROM events WHERE run_id = ? ORDER BY seq",
      )
      .all(runId)
      .map((r) => ({ seq: r.seq, kind: r.kind, payload: JSON.parse(r.payload) }));
  }

  append(runId: string, kind: StoredEvent["kind"], payload: Record<string, unknown>, at: Date): void {
    const row = this.db.query<{ n: number | null }, [string]>("SELECT MAX(seq) AS n FROM events WHERE run_id = ?").get(runId);
    this.db
      .query("INSERT INTO events (run_id, seq, kind, payload, created_at) VALUES (?, ?, ?, ?, ?)")
      .run(runId, (row?.n ?? 0) + 1, kind, JSON.stringify(payload), at.toISOString());
  }

  savePlan(plan: Plan): void {
    this.db
      .query("INSERT OR REPLACE INTO plans (id, review_id, json, rationale, created_at) VALUES (?, ?, ?, ?, ?)")
      .run(plan.id, plan.review_id, plan.json, plan.rationale, plan.created_at);
  }

  saveDecision(d: Decision): void {
    this.db
      .query("INSERT OR REPLACE INTO gate_decisions (id, plan_id, candidate, verdict, reasons, trace_url) VALUES (?, ?, ?, ?, ?, ?)")
      .run(`${d.plan_id}:${d.candidate}`, d.plan_id, d.candidate, d.verdict, JSON.stringify(d.reasons), d.trace_url);
  }

  close(): void {
    this.db.close();
  }
}

/** Rebuilds a run from its events: the conversation, the last state snapshot and the LLM spend. */
function rebuild(events: StoredEvent[]) {
  const messages: ChatMessage[] = [];
  let state = initialState();
  let llmUsd = 0;
  let unpriced = 0;
  let turns = 0;
  let ended: RunResult | null = null;
  for (const e of events) {
    const p = e.payload;
    if (Array.isArray(p.messages)) messages.push(...(p.messages as ChatMessage[]));
    if (p.message) messages.push(p.message as ChatMessage);
    if (p.state) state = p.state as RunState;
    if (e.kind === "llm") {
      turns++;
      if (typeof p.costUsd === "number") llmUsd += p.costUsd;
      else unpriced++;
    }
    ended = e.kind === "end" ? (p.result as RunResult) : null;
  }
  return { messages, state, llmUsd, unpriced, turns, ended };
}

/** A fresh run id, e.g. "run-20261010143000-k3x9". */
export const newRunId = (now: Date) =>
  `run-${now.toISOString().replace(/\D/g, "").slice(0, 14)}-${Math.random().toString(36).slice(2, 6)}`;

/** Runs (or resumes) the coordinator until promotion, an honest give-up, the budget or MAX_TURNS. */
export async function runCoordinator(opts: CoordinatorOptions): Promise<RunResult> {
  const now = opts.now ?? (() => new Date());
  const maxTurns = opts.maxTurns ?? MAX_TURNS;
  const store = new EventStore(opts.dbPath ?? DEFAULT_DB);
  const runId = opts.runId ?? newRunId(now());
  const reviewId = opts.reviewId ?? runId;
  try {
    const prior = store.events(runId);
    const resumed = prior.length > 0;
    let { messages, state, llmUsd, unpriced, turns, ended } = rebuild(prior);
    if (ended && FINAL.has(ended.outcome)) return { ...ended, resumed: true };

    const log = (kind: StoredEvent["kind"], payload: Record<string, unknown>) => store.append(runId, kind, payload, now());
    if (!resumed) {
      const start: ChatMessage[] = [
        { role: "system", content: SYSTEM_PROMPT },
        {
          role: "user",
          content: `Review ${opts.repo}. Run id ${runId}. Budget $${opts.budgetUsd} for LLM and replay cost together. Start by reading the scorecard.`,
        },
      ];
      messages.push(...start);
      log("start", { messages: start, config: { repo: opts.repo, budgetUsd: opts.budgetUsd, reviewId } });
    }

    const ctx: ToolContext = {
      runId,
      repo: opts.repo,
      budgetUsd: opts.budgetUsd,
      spentUsd: () => llmUsd + state.replayUsd,
    };
    let planPath: string | null = null;
    const decisionsPath = join(opts.outDir, "decisions.json");
    const writePlan = () => {
      const plan = state.plans.at(-1);
      if (!plan) return;
      planPath = writePlanFile(opts.outDir, planFile(runId, state.plans));
      store.savePlan({
        id: planId(runId, plan),
        review_id: reviewId,
        json: JSON.stringify(plan.body),
        rationale: plan.body.rationale,
        created_at: plan.created_at,
      });
    };
    const result = (outcome: StopReason, summary: string): RunResult => ({
      runId,
      outcome,
      promoted: state.promoted,
      summary,
      turns,
      llmUsd,
      replayUsd: state.replayUsd,
      spentUsd: llmUsd + state.replayUsd,
      unpricedLlmCalls: unpriced,
      decisions: state.decisions,
      planPath,
      decisionsPath,
      resumed,
    });
    const writeDecisions = (r: RunResult) => {
      mkdirSync(opts.outDir, { recursive: true });
      const doc = {
        run_id: runId,
        repo: opts.repo,
        outcome: r.outcome,
        promoted: r.promoted,
        summary: r.summary,
        budget_usd: opts.budgetUsd,
        spent: { llm_usd: r.llmUsd, replay_usd: r.replayUsd, total_usd: r.spentUsd, unpriced_llm_calls: r.unpricedLlmCalls },
        turns: r.turns,
        excluded_tasks: state.excludedTasks,
        decisions: state.decisions,
      };
      writeFileSync(decisionsPath, JSON.stringify(doc, null, 2) + "\n");
    };
    writePlan();

    const overBudget = () => ctx.spentUsd() >= opts.budgetUsd;
    const budgetStop = () =>
      `budget stop: spent $${ctx.spentUsd().toFixed(4)} of $${opts.budgetUsd} (LLM $${llmUsd.toFixed(4)}, replays $${state.replayUsd.toFixed(4)})`;

    const loop = async (): Promise<RunResult> => {
      for (;;) {
        // Answer the latest assistant turn's tool calls that have no answer yet (all of them, unless resuming).
        const lastAssistant = [...messages].reverse().find((m) => m.role === "assistant");
        if (lastAssistant?.role === "assistant" && lastAssistant.tool_calls?.length) {
          const answered = new Set(messages.flatMap((m) => (m.role === "tool" ? [m.tool_call_id] : [])));
          for (const call of lastAssistant.tool_calls) {
            if (answered.has(call.id)) continue;
            if (overBudget()) return result("budget", budgetStop());
            const plans = state.plans.length;
            const decisions = state.decisions.length;
            const out = await executeToolCall(call, state, ctx, opts.backend);
            const message: ChatMessage = { role: "tool", tool_call_id: call.id, content: out.content };
            messages.push(message);
            log("tool", { message, name: call.name, ok: out.ok, state });
            if (state.plans.length !== plans) writePlan();
            for (const d of state.decisions.slice(decisions)) store.saveDecision(d);
            if (state.promoted && call.name === "promote" && out.ok) {
              return result("promoted", `the gate approved ${state.promoted} and it was promoted`);
            }
            if (state.finished) return result(state.finished.outcome, state.finished.summary);
          }
        }
        if (state.notes.length) {
          const message: ChatMessage = { role: "user", content: `[roster] ${state.notes.splice(0).join("\n")}` };
          messages.push(message);
          log("note", { message, state });
        }
        if (overBudget()) return result("budget", budgetStop());
        if (turns >= maxTurns) return result("max_turns", `stopped after ${turns} turns (limit ${maxTurns})`);

        let reply;
        try {
          reply = await opts.llm.chat({ messages, tools: TOOL_SPECS, model: opts.model, temperature: opts.temperature ?? 0 });
        } catch (err) {
          return result("llm_error", `LLM call failed: ${err instanceof Error ? err.message : String(err)}`);
        }
        turns++;
        if (reply.costUsd === null) unpriced++;
        else llmUsd += reply.costUsd;
        messages.push(reply.message);
        log("llm", { message: reply.message, costUsd: reply.costUsd, usage: reply.usage, model: reply.model });
        if (reply.toolCalls.length === 0) {
          return result("stopped", reply.message.content ?? "the model stopped without calling a tool");
        }
      }
    };

    const finalResult = await withSpan("AGENT", "coordinator", { repo: opts.repo }, async (span) => {
      const r = await loop();
      span.setAttribute(ATTR.costUsd, r.spentUsd);
      return r;
    });
    log("end", { result: finalResult });
    writeDecisions(finalResult);
    return finalResult;
  } finally {
    store.close();
  }
}

